import heapq

class Node:
    def __init__(self, idx, val, cnt):
        self.idx = idx
        self.val = val
        self.cnt = cnt

    def __lt__(self, other):
        if self.val != other.val:
            return self.val < other.val
        if self.cnt != other.cnt:
            return self.cnt < other.cnt
        return self.idx > other.idx

n = int(input())
a = list(map(int, input().split()))

heap = []
ans = [0] * n

for i in range(n - 1):
    heapq.heappush(heap, Node(i, a[i], 0))
    top = heapq.heappop(heap)
    top.cnt += 1
    ans[top.idx] += 1
    heapq.heappush(heap, top)

print(*ans)
```
### java
```java
import java.util.PriorityQueue;
import java.util.Scanner;

class Node implements Comparable<Node> {
    int idx, val, cnt;

    public Node(int idx, int val, int cnt) {
        this.idx = idx;
        this.val = val;
        this.cnt = cnt;
    }

    @Override
    public int compareTo(Node other) {
        if (this.val != other.val) {
            return Integer.compare(this.val, other.val);
        }
        if (this.cnt != other.cnt) {
            return Integer.compare(this.cnt, other.cnt);
        }
        return Integer.compare(other.idx, this.idx); // Note the reversed order for idx
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] a = new int[n];
        int[] ans = new int[n];

        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }

        PriorityQueue<Node> heap = new PriorityQueue<>();

        for (int i = 0; i < n - 1; i++) {
            heap.offer(new Node(i, a[i], 0));
            Node top = heap.poll();
            top.cnt += 1;
            ans[top.idx] += 1;
            heap.offer(top);
        }

        for (int i = 0; i < n; i++) {
            System.out.print(ans[i] + " ");
        }
    }
}
```
